def amicable_numbers_sum(upper_limit):
    def sum_of_divisors(n):
        return sum([i for i in range(1, n) if n % i == 0])

    amicable_sum = 0
    for num in range(2, upper_limit + 1):
        if num not in amicable_sum:
            partner = sum_of_divisors(num)
            if num == sum_of_divisors(partner) and num != partner:
                amicable_sum += num + partner
    return amicable_sum
```

